css:
.bb-slip { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; }
.bb-slip h3 { margin: 0 0 4px 0; font-size: 15pt; }
.bb-slip .grp { font-size: 22pt; font-weight: 900; border: 2px solid #000; padding: 2px 10px; display: inline-block; }
.bb-slip table { width: 100%; border-collapse: collapse; margin-top: 8px; }
.bb-slip th, .bb-slip td { border: 1px solid #555; padding: 4px; vertical-align: middle; }
.bb-slip .bc svg { height: 32px; width: auto; }
.bb-slip .box { display: inline-block; width: 12px; height: 12px; border: 1px solid #000; margin-right: 6px; vertical-align: middle; }
.bb-slip .warn { border: 2px solid #c00; color: #c00; font-weight: bold; padding: 4px; margin: 6px 0; }
